INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z8-q38','nism-5b-z8','Real return is:','["Return before expenses","Nominal return adjusted for inflation","Return net of tax only","Return on a real-estate investment"]',1,'FD 7% with 8% inflation gives a negative real return.',38) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z8-q39','nism-5b-z8','An investor holds 190 units under the IDCW Reinvestment option. IDCW is ₹2 per unit and the ex-IDCW NAV is ₹12. The additional units allotted are:','["27.14","380.00","31.67","63.33"]',2,'Units = (190 × 2) ÷ 12 = 31.67.',39) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z8-q40','nism-5b-z8','Mutual fund portfolios must be disclosed on websites within:','["10 days of month-end/half-year","1 year","3 months","30 days"]',0,'Debt schemes also disclose a fortnightly portfolio within 5 days.',40) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z8-q41','nism-5b-z8','An investor holds 330 units under the IDCW Reinvestment option. IDCW is ₹1.5 per unit and the ex-IDCW NAV is ₹18. The additional units allotted are:','["55.00","25.38","495.00","27.50"]',3,'Units = (330 × 1.5) ÷ 18 = 27.50.',41) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z8-q42','nism-5b-z8','Seasoning in securitisation refers to:','["The proportion of instalments already repaid","The date of NFO","The loan size","The rating of the SPV"]',0,'In the deck, 80% instalments repaid is more seasoned than 10%.',42) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z8-q43','nism-5b-z8','The three mandatory scheme-related documents are:','["SAI, SEBI circular and factsheet","SID, SAI and KIM","KYC, KIM and CAS","SID, TER and CAS"]',1,'The fund factsheet is non-mandatory.',43) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z8-q44','nism-5b-z8','Overnight funds may keep at most ___ in G-secs/T-bills of up to 30 days as margin.','["20%","15%","10%","5%"]',3,'Overnight funds may place ≤5% as margin.',44) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z8-q45','nism-5b-z8','In the SEBI CAGR method with IDCW, the IDCW is assumed to be:','["Reinvested at the next day''s NAV","Reinvested at the ex-IDCW NAV","Paid out and ignored","Reinvested at face value"]',1,'This increases the number of units.',45) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z8-q46','nism-5b-z8','A Transfer of IDCW Plan (DTP) invests the IDCW of one scheme into:','["The same scheme at face value","Another scheme of the same MF","A bank deposit","A scheme of any AMC"]',1,'It overrides payout or reinvestment.',46) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z8-q47','nism-5b-z8','The I-Bex sub-indices Si-Bex, Mi-Bex and Li-Bex refer to maturities of:','["Up to 1 year, 1–5 years and 5–10 years","1–3 years, 3–7 years and over 7 years","1–2, 2–4 and 4–6 years","0–91 days, 91–365 days and above"]',1,'They are ICICI Securities indices.',47) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z8-q48','nism-5b-z8','A scheme with average net assets of ₹5600 crore incurs total recurring expenses of ₹3.60 crore in a year. Its expense ratio is:','["0.032%","0.129%","0.064%","0.096%"]',2,'TER = 3.60 ÷ 5600 × 100 = 0.064%.',48) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
