INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z8-q50','nism-5b-z8','In a mutual fund, which risk is MOSTLY borne by the investor rather than the fund manager?','["Duration positioning risk","Credit analysis risk","Stock selection risk","Market-wide risk"]',3,'The fund manager can reduce it only by holding cash within SEBI limits.',50) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z8-q51','nism-5b-z8','Relative return has the weakness that it:','["Excludes IDCW","Cannot be computed","Includes taxes","Ignores the different risk levels taken"]',3,'Hence risk-adjusted returns are used.',51) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z8-q52','nism-5b-z8','Pledged units cannot be sold or switched until:','["The unitholder dies","SEBI approves","The AMC approves","The pledgee gives a written NOC"]',3,'Units must be out of lock-in to be pledged.',52) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z8-q53','nism-5b-z8','In an SIP, rupee cost averaging means that over time:','["NAV never falls","The average cost per unit tends to be lower than the average NAV","Returns are guaranteed","No tax is payable"]',1,'In the deck example, average cost ₹10.55 against average NAV ₹10.67.',53) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
