INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z11-q11','nism-5b-z11','A portfolio of ₹34,00,000 is 40:60 equity:debt. Equity rises 15% and debt is unchanged. To rebalance to the original ratio, the amount of equity to be sold is:','["₹5,10,000","₹1,83,600","₹1,22,400","₹2,04,000"]',2,'New equity = 1564000; target = 1441600; sell the excess.',11) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z11-q12','nism-5b-z11','An investor sells equity-oriented fund units after 18 months with a long-term capital gain of ₹3,75,000 (no other LTCG in the year). As per the rates in the current workbook, the LTCG tax (ignoring cess) is:','["₹46,875","₹31,250","₹50,000","₹75,000"]',1,'Taxable = 375000 − 1,25,000; tax at 12.5% = ₹31,250.',12) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z11-q13','nism-5b-z11','A scheme has total assets of ₹123.50 crore, liabilities (other than to unitholders) of ₹1.70 crore and 1.30 crore units outstanding. Its NAV per unit is:','["₹96.31","₹52.96","₹93.69","₹95.00"]',2,'NAV = (123.50 − 1.70) ÷ 1.30 = ₹93.69.',13) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
