INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z11-q59','nism-5b-z11','In the SEBI CAGR method with IDCW, the IDCW is assumed to be:','["Reinvested at the ex-IDCW NAV","Reinvested at the next day''s NAV","Reinvested at face value","Paid out and ignored"]',0,'This increases the number of units.',59) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
