INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z13-q38','nism-5b-z13','Units transmitted on the death of the first holder in a joint folio go to:','["The legal heirs","The second holder, who becomes the first holder","The nominee","The AMC"]',1,'Where there is a nominee and a joint holder, the joint holder''s right prevails.',38) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
