INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z13-q40','nism-5b-z13','A portfolio of ₹18,00,000 is 50:50 equity:debt. Equity rises 20% and debt is unchanged. To rebalance to the original ratio, the amount of equity to be sold is:','["₹90,000","₹3,60,000","₹1,80,000","₹1,35,000"]',0,'New equity = 1080000; target = 990000; sell the excess.',40) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z13-q41','nism-5b-z13','The cut-off time for redemptions in equity and debt schemes (excluding liquid) is:','["5:00 pm","3:00 pm","2:00 pm","1:30 pm"]',1,'Same-day NAV if before the cut-off, otherwise next business day.',41) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
INSERT INTO questions (id,quiz_id,question,options,answer,explanation,sort) VALUES ('nism-5b-z13-q42','nism-5b-z13','The behavioural bias in which the pain of a loss is felt more than the joy of an equal gain is:','["Familiarity bias","Loss aversion","Herd mentality","Recency bias"]',1,'Loss aversion was described by Kahneman and Tversky.',42) ON CONFLICT(id) DO UPDATE SET quiz_id=excluded.quiz_id,question=excluded.question,options=excluded.options,answer=excluded.answer,explanation=excluded.explanation,sort=excluded.sort;
